// Contiguous Block Setup
#define BLOCK_SIZE 10
int buffer[BLOCK_SIZE] = {0};
int* p_start = buffer;

// Basic Arithmetic: p_start moves by sizeof(int)
int val_at_4 = *(p_start + 4);

// Iterative Traversal (Optimized Loop)
for (int i = 0; i < BLOCK_SIZE; i++) {
    // p_start[i] is equivalent to *(p_start + i)
    p_start[i] = i * 2;
}

// Byte-Level Manipulation (Requires char* or uint8_t*)
unsigned char raw_bytes[4] = {0x11, 0x22, 0x33, 0x44};
unsigned char* byte_ptr = raw_bytes;

// Interpreting byte offset 2 as the start of an int (Type punning)
int value = *(int*)(byte_ptr);
byte_ptr += 2; // Advance pointer 2 bytes
unsigned char third_byte = *byte_ptr; // 0x33
